// =====================================================
// WebDavClient.ets - Minimal WebDAV client via @ohos.net.http
// Supports PUT/GET/HEAD/DELETE with Basic Auth.
// =====================================================

import http from '@ohos.net.http';
import { Base64Util } from './Base64Util';

import type { IWebDavBackend } from './IWebDavBackend';

export interface WebDavResponse {
  statusCode: number;
  headers: Record<string, string>;
  body: string;
}

interface HttpErrorInfo {
  code: string;
  message: string;
}

export class WebDavClient implements IWebDavBackend {
  private endpoint: string;
  private authHeader: string;
  private static readonly MAX_REDIRECTS: number = 2;

  constructor(endpoint: string, username: string, password: string) {
    this.endpoint = endpoint.replace(/\/+$/g, '');
    const raw = `${username}:${password}`;
    this.authHeader = `Basic ${Base64Util.encodeUtf8String(raw)}`;
  }

  async get(path: string): Promise<WebDavResponse> {
    return this.request(http.RequestMethod.GET, path, {}, undefined);
  }

  async head(path: string): Promise<WebDavResponse> {
    return this.request(http.RequestMethod.HEAD, path, {}, undefined);
  }

  async put(path: string, body: string, contentType: string = 'application/octet-stream', extraHeaders: Record<string, string> = {}, ensureDir: boolean = true): Promise<WebDavResponse> {
    const headers: Record<string, string> = { 'Content-Type': contentType };
    Object.keys(extraHeaders).forEach((key: string) => {
      headers[key] = extraHeaders[key];
    });

    // 自动创建父目录
    if (ensureDir) {
      await this.ensureParentExists(path);
    }

    return this.request(http.RequestMethod.PUT, path, headers, body);
  }

  private async ensureParentExists(path: string): Promise<void> {
    const lastSlash = path.lastIndexOf('/');
    if (lastSlash <= 0) return;

    const parent = path.substring(0, lastSlash);
    if (parent.length === 0 || parent === '/') return;

    try {
      const headRes = await this.head(parent);
      if (headRes.statusCode === 404) {
        console.info(`[WebDavClient] Creating parent directory: ${parent}`);
        // 递归创建父目录
        await this.ensureParentExists(parent);
        await this.mkcol(parent);
      }
    } catch (e) {
      // 忽略检查错误，让 PUT 自己失败
      const errMsg = e instanceof Error ? e.message : String(e);
      console.warn(`[WebDavClient] ensureParentExists failed for ${parent}: ${errMsg} (will continue)`);
    }
  }

  async delete(path: string): Promise<WebDavResponse> {
    return this.request(http.RequestMethod.DELETE, path, {}, undefined);
  }

  async mkcol(path: string): Promise<WebDavResponse> {
    // 使用 PUT 创建目录（WebDAV 服务器通常支持 PUT 到目录路径）
    // 或者尝试 PUT 一个空文件到 .keep 文件来创建目录
    const keepFile = path.endsWith('/') ? `${path}.keep` : `${path}/.keep`;
    return this.request(http.RequestMethod.PUT, keepFile, { 'Content-Type': 'text/plain' }, '');
  }

  private buildUrl(path: string): string {
    if (path.startsWith('http://') || path.startsWith('https://')) {
      return path;
    }
    if (!path.startsWith('/')) {
      path = `/${path}`;
    }
    return `${this.endpoint}${path}`;
  }

  private normalizeHeaders(headers: Record<string, string | string[] | number | undefined>): Record<string, string> {
    const out: Record<string, string> = {};
    for (const k of Object.keys(headers)) {
      const v = headers[k];
      if (v === undefined) continue;
      if (Array.isArray(v)) {
        out[k.toLowerCase()] = v.join(',');
      } else {
        out[k.toLowerCase()] = String(v);
      }
    }
    return out;
  }

  private async request(method: http.RequestMethod, path: string, headers: Record<string, string>, body?: string): Promise<WebDavResponse> {
    const requestId = this.newRequestId();
    return this.requestWithRedirect(method, path, headers, body, WebDavClient.MAX_REDIRECTS, requestId);
  }

  private async requestWithRedirect(
    method: http.RequestMethod,
    path: string,
    headers: Record<string, string>,
    body: string | undefined,
    redirectsLeft: number,
    requestId: string
  ): Promise<WebDavResponse> {
    const startMs = Date.now();
    const request = http.createHttp();

    const url = this.buildUrl(path);
    // Merge headers manually to avoid spread operator issues
    const allHeaders: Record<string, string> = {
      'Authorization': this.authHeader,
      'Accept': '*/*'
    };
    // Add custom headers
    Object.keys(headers).forEach((key: string) => {
      allHeaders[key] = headers[key];
    });

    try {
      const options: http.HttpRequestOptions = {
        method,
        header: allHeaders,
        connectTimeout: 15000,
        readTimeout: 20000
      };
      if (body !== undefined && (method === http.RequestMethod.PUT || method === http.RequestMethod.POST)) {
        options.extraData = body;
      }
      const res = await request.request(url, options);

      const statusCode = res.responseCode ?? 0;
      // Ensure res.header is treated as the correct type
      const resHeaders = this.normalizeHeaders(res.header as Record<string, string | string[] | number | undefined>);
      const raw = res.result;
      let bodyStr = '';
      if (typeof raw === 'string') {
        bodyStr = raw;
      } else if (raw instanceof ArrayBuffer) {
        // Decode as UTF-8-ish text (best-effort)
        const bytes = new Uint8Array(raw);
        bodyStr = '';
        for (const b of bytes) bodyStr += String.fromCharCode(b);
      } else {
        bodyStr = '';
      }

      request.destroy();
      const elapsed = Date.now() - startMs;
      if (redirectsLeft > 0 && (statusCode === 301 || statusCode === 302 || statusCode === 303 || statusCode === 307 || statusCode === 308)) {
        const location = resHeaders['location'] ?? '';
        console.info(`[WebDAV] ${String(method)} ${url} - ${statusCode} (redirect: ${location}) in ${elapsed}ms`);
        if (location.length > 0) {
          return this.requestWithRedirect(method, location, headers, body, redirectsLeft - 1, requestId);
        }
      }
      console.info(`[WebDAV] ${String(method)} ${url} - ${statusCode} in ${elapsed}ms`);
      return { statusCode, headers: resHeaders, body: bodyStr };
    } catch (e) {
      request.destroy();
      const err = this.buildHttpErrorInfo(e as (object | string | number | boolean | null | undefined));
      const elapsed = Date.now() - startMs;
      console.error(`[WebDAV] ${String(method)} ${url} - ERROR ${err.code}: ${err.message} (${elapsed}ms)`);
      return { statusCode: 0, headers: {}, body: err.message };
    }
  }

  private buildHttpErrorInfo(e: object | string | number | boolean | null | undefined): HttpErrorInfo {
    if (e === null || e === undefined) {
      return { code: '', message: 'unknown_error' };
    }
    if (typeof e === 'string' || typeof e === 'number' || typeof e === 'boolean') {
      return { code: '', message: String(e) };
    }
    if (e instanceof Error) {
      const name = e.name ?? '';
      const msg = e.message ?? '';
      if (name.length > 0 && msg.length > 0) {
        return { code: '', message: `${name}: ${msg}` };
      }
      if (msg.length > 0) {
        return { code: '', message: msg };
      }
      return { code: '', message: name.length > 0 ? name : 'error' };
    }

    const obj = e as Record<string, string | number | boolean | object | undefined | null>;
    const codeVal = obj['code'];
    const messageVal = obj['message'];
    const nameVal = obj['name'];

    const code = (typeof codeVal === 'string' || typeof codeVal === 'number') ? String(codeVal) : '';
    const message = typeof messageVal === 'string' ? messageVal : '';
    const name = typeof nameVal === 'string' ? nameVal : '';
    const raw = this.safeJsonStringify(obj);

    if (code.length > 0 || message.length > 0) {
      const title = name.length > 0 ? name : 'BusinessError';
      const core = `${title}: ${message.length > 0 ? message : 'unknown'}`;
      if (raw.length > 0) {
        return { code, message: `${core} raw=${raw}` };
      }
      return { code, message: core };
    }
    if (raw.length > 0) {
      return { code: '', message: raw };
    }
    return { code: '', message: 'unknown_error_object' };
  }

  private safeJsonStringify(obj: Record<string, string | number | boolean | object | undefined | null>): string {
    try {
      const s = JSON.stringify(obj);
      if (typeof s === 'string') {
        return s;
      }
      return '';
    } catch (e) {
      return '';
    }
  }

  private newRequestId(): string {
    const rand = Math.random().toString(36).substring(2, 8);
    return `${Date.now()}_${rand}`;
  }
}
    const msg = e instanceof Error ? e.message : String(e);
    const stack = e instanceof Error ? e.stack : '';
    console.error(`[WebDavSyncTask] Backup with encryption failed: ${msg}`);
    if (stack) {
      console.error(`[WebDavSyncTask] Stack trace: ${stack}`);
    }
    const errorResult: BackupTaskResult = {
      success: false,
      message: '备份失败',
      detail: msg
    };
    return errorResult;
  }
}

/**
 * 执行下载任务（在 TaskPool 中运行）
 */
@Concurrent
export async function executeDownload(params: DownloadTaskParams): Promise<DownloadTaskResult> {
  console.info(`[WebDavSyncTask] Starting download in taskpool file=${params.remoteFile}`);
  const startMs = Date.now();

  try {
    // 创建 WebDAV 客户端
    const client = new WebDavClient(params.endpoint, params.username, params.password);

    // 下载数据
    console.info(`[WebDavSyncTask] Downloading from ${params.remoteFile}`);
    const downloadStartMs = Date.now();
    const getRes = await client.get(params.remoteFile);
    const downloadMs = Date.now() - downloadStartMs;
    
    if (getRes.statusCode === 404) {
      console.info(`[WebDavSyncTask] File not found (404): ${params.remoteFile}`);
      const result: DownloadTaskResult = { success: true, data: '', detail: '文件不存在' };
      return result;
    }
    if (getRes.statusCode < 200 || getRes.statusCode >= 300) {
      console.error(`[WebDavSyncTask] Download failed status=${getRes.statusCode} body=${getRes.body.substring(0, 200)}`);
      const result: DownloadTaskResult = { success: false, data: '', detail: `GET ${getRes.statusCode}: ${getRes.body}` };
      return result;
    }

    console.info(`[WebDavSyncTask] Download complete size=${getRes.body.length} chars ms=${downloadMs}`);

    // 解密数据
    let plain = '';
    try {
      console.info('[WebDavSyncTask] Decrypting downloaded data');
      const decryptStartMs = Date.now();
      plain = await WebDavCrypto.decryptUtf8Async(getRes.body, params.syncPassword);
      const decryptMs = Date.now() - decryptStartMs;
      console.info(`[WebDavSyncTask] Decryption complete plain_size=${plain.length} chars ms=${decryptMs}`);
    } catch (ce) {
      const errorMsg = ce instanceof CryptoError ? ce.message : String(ce);
      console.error(`[WebDavSyncTask] Decryption failed: ${errorMsg}`);
      if (ce instanceof Error && ce.stack) {
        console.error(`[WebDavSyncTask] Decryption stack: ${ce.stack}`);
      }
      let userFriendlyMsg = errorMsg;
      if (errorMsg.includes('MAC verification failed')) {
        userFriendlyMsg = '同步密码错误或云端数据已损坏。建议：1)检查同步密码是否正确；2)点击"立即同步"重新上传本地数据覆盖云端';
      }
      const result: DownloadTaskResult = { success: false, data: '', detail: userFriendlyMsg };
      return result;
    }

    const totalMs = Date.now() - startMs;
    console.info(`[WebDavSyncTask] Download task complete total_ms=${totalMs}`);
    const successResult: DownloadTaskResult = { success: true, data: plain, detail: '' };
    return successResult;

  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    const stack = e instanceof Error ? e.stack : '';
    console.error(`[WebDavSyncTask] Download failed: ${msg}`);
    if (stack) {
      console.error(`[WebDavSyncTask] Stack trace: ${stack}`);
    }
    const errorResult: DownloadTaskResult = { success: false, data: '', detail: msg };
    return errorResult;
  }
}

/**
 * 执行上传任务（在 TaskPool 中运行）
 */
@Concurrent
export async function executeUpload(params: UploadTaskParams): Promise<UploadTaskResult> {
  console.info('[WebDavSyncTask] Starting upload in taskpool');

  try {
    // 创建 WebDAV 客户端
    const client = new WebDavClient(params.endpoint, params.username, params.password);

    // 上传数据
    const putRes = await client.put(params.remoteFile, params.data, 'application/json');
    if (putRes.statusCode < 200 || putRes.statusCode >= 300) {
      const result: UploadTaskResult = { success: false, detail: `PUT ${putRes.statusCode}: ${putRes.body}` };
      return result;
    }

    const successResult: UploadTaskResult = { success: true, detail: '' };
    return successResult;

  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    console.error('[WebDavSyncTask] Upload failed:', msg);
    const errorResult: UploadTaskResult = { success: false, detail: msg };
    return errorResult;
  }
}

/**
 * 执行加密+上传任务（在 TaskPool 中运行）
 * 在后台线程中完成加密和上传，避免阻塞 UI 线程
 */
@Concurrent
export async function executeUploadWithEncrypt(params: UploadTaskWithEncryptParams): Promise<UploadTaskResult> {
  console.info(`[WebDavSyncTask] Starting upload with encryption in taskpool file=${params.remoteFile} data_size=${params.plainData.length} chars`);
  const startMs = Date.now();

  try {
    // 在 TaskPool 中加密数据
    console.info('[WebDavSyncTask] Encrypting data in background');
    const encryptStartMs = Date.now();
    const encrypted = await WebDavCrypto.encryptUtf8Async(params.plainData, params.syncPassword);
    const encryptMs = Date.now() - encryptStartMs;
    console.info(`[WebDavSyncTask] Encryption complete encrypted_size=${encrypted.length} chars ms=${encryptMs}`);

    // 创建 WebDAV 客户端
    const client = new WebDavClient(params.endpoint, params.username, params.password);

    // 上传数据
    console.info(`[WebDavSyncTask] Uploading encrypted data to ${params.remoteFile}`);
    const uploadStartMs = Date.now();
    const putRes = await client.put(params.remoteFile, encrypted, 'application/json');
    const uploadMs = Date.now() - uploadStartMs;
    
    if (putRes.statusCode < 200 || putRes.statusCode >= 300) {
      console.error(`[WebDavSyncTask] Upload failed status=${putRes.statusCode} body=${putRes.body.substring(0, 200)}`);
      const result: UploadTaskResult = { success: false, detail: `PUT ${putRes.statusCode}: ${putRes.body}` };
      return result;
    }

    const totalMs = Date.now() - startMs;
    console.info(`[WebDavSyncTask] Upload completed successfully total_ms=${totalMs} encrypt_ms=${encryptMs} upload_ms=${uploadMs}`);
    const successResult: UploadTaskResult = { success: true, detail: '' };
    return successResult;

  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    const stack = e instanceof Error ? e.stack : '';
    console.error(`[WebDavSyncTask] Upload with encryption failed: ${msg}`);
    if (stack) {
      console.error(`[WebDavSyncTask] Stack trace: ${stack}`);
    }
    const errorResult: UploadTaskResult = { success: false, detail: msg };
    return errorResult;
  }
}

/**
 * 执行事件下载任务（在 TaskPool 中运行）
 */
@Concurrent
export async function executeEventsDownload(params: DownloadTaskParams): Promise<DownloadTaskResult> {
  console.info('[WebDavSyncTask] Starting events download in taskpool');
  // 直接复制 executeDownload 的实现，避免调用其他函数
  try {
    const client = new WebDavClient(params.endpoint, params.username, params.password);
    const getRes = await client.get(params.remoteFile);
    if (getRes.statusCode === 404) {
      const result: DownloadTaskResult = { success: true, data: '', detail: '文件不存在' };
      return result;
    }
    if (getRes.statusCode < 200 || getRes.statusCode >= 300) {
      const result: DownloadTaskResult = { success: false, data: '', detail: `GET ${getRes.statusCode}: ${getRes.body}` };
      return result;
    }
    let plain = '';
    try {
      plain = await WebDavCrypto.decryptUtf8Async(getRes.body, params.syncPassword);
    } catch (ce) {
      const errorMsg = ce instanceof CryptoError ? ce.message : String(ce);
      let userFriendlyMsg = errorMsg;
      if (errorMsg.includes('MAC verification failed')) {
        userFriendlyMsg = '同步密码错误或云端数据已损坏。建议：1)检查同步密码是否正确；2)点击"立即同步"重新上传本地数据覆盖云端';
      }
      const result: DownloadTaskResult = { success: false, data: '', detail: userFriendlyMsg };
      return result;
    }
    const successResult: DownloadTaskResult = { success: true, data: plain, detail: '' };
    return successResult;
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    console.error('[WebDavSyncTask] Download failed:', msg);
    const errorResult: DownloadTaskResult = { success: false, data: '', detail: msg };
    return errorResult;
  }
}

/**
 * 执行事件上传任务（在 TaskPool 中运行）
 */
@Concurrent
export async function executeEventsUpload(params: UploadTaskParams): Promise<UploadTaskResult> {
  console.info('[WebDavSyncTask] Starting events upload in taskpool');
  // 直接复制 executeUpload 的实现，避免调用其他函数
  try {
    const client = new WebDavClient(params.endpoint, params.username, params.password);
    const putRes = await client.put(params.remoteFile, params.data, 'application/json');
    if (putRes.statusCode < 200 || putRes.statusCode >= 300) {
      const result: UploadTaskResult = { success: false, detail: `PUT ${putRes.statusCode}: ${putRes.body}` };
      return result;
    }
    const successResult: UploadTaskResult = { success: true, detail: '' };
    return successResult;
  } catch (e) {
    const msg = e instanceof Error ? e.message : String(e);
    console.error('[WebDavSyncTask] Upload failed:', msg);
    const errorResult: UploadTaskResult = { success: false, detail: msg };
    return errorResult;
  }
}

/**
 * 执行解密任务（在 TaskPool 中运行）
 * 专门用于备份文件的解密，避免阻塞 UI 线程
 */
@Concurrent
export async function executeDecrypt(params: DecryptTaskParams): Promise<DecryptTaskResult> {
  console.info(`[WebDavSyncTask] Starting decryption in taskpool data_size=${params.encryptedData.length} chars`);
  const startMs = Date.now();

  try {
    console.info('[WebDavSyncTask] Decrypting data in background');
    const plain = await WebDavCrypto.decryptUtf8Async(params.encryptedData, params.syncPassword);
    
    const totalMs = Date.now() - startMs;
    console.info(`[WebDavSyncTask] Decryption complete plain_size=${plain.length} chars ms=${totalMs}`);
    
    const successResult: DecryptTaskResult = { 
      success: true, 
      data: plain, 
      detail: '' 
    };
    return successResult;

    return this.composeRemotePath(this.remoteLayoutBase, this.remoteLayoutPrefix, WORDS_DELTA_FILE_NAME);
  }

  private definitionsFilePath(): string {
    return this.composeRemotePath(this.remoteLayoutBase, this.remoteLayoutPrefix, DEFINITIONS_FILE_NAME);
  }

  private isCollectionReachable(statusCode: number): boolean {
    if (statusCode >= 200 && statusCode < 400) {
      return true;
    }
    return statusCode === 405;
  }

  private async probeRootWritable(client: IWebDavBackend, prefix: string): Promise<WebDavSyncResult | null> {
    const probeName = `.probe_${Date.now()}.txt`;
    const probePath = this.composeRemotePath('/', prefix, probeName);
    const putRes = await client.put(probePath, 'probe', 'text/plain');
    if (putRes.statusCode >= 200 && putRes.statusCode < 300) {
      await client.delete(probePath);
      return null;
    }
    if (putRes.statusCode === 401 || putRes.statusCode === 403) {
      const msg = putRes.statusCode === 401 ? '鉴权失败（可能需要应用专用密码）' : '根目录权限不足，无法使用根目录前缀模式';
      return WebDavSyncResult.fail('WebDAV 连接失败', `STEP endpoint PUT ${putRes.statusCode}: ${msg}；请在 WebDAV 端创建 ${this.settings.remoteRoot} 或填写一个已存在且有权限的远端目录`);
    }
    if (putRes.statusCode === 409) {
      return WebDavSyncResult.fail('WebDAV 连接失败', `STEP endpoint PUT 409: 路径不存在（AncestorNotFound）；请检查 WebDAV 地址是否指向可用的根目录（例如以 /dav/ 结尾），或先在 WebDAV 端创建 ${this.settings.remoteRoot}`);
    }
    return WebDavSyncResult.fail('WebDAV 连接失败', `STEP endpoint PUT ${putRes.statusCode}: ${putRes.body}`);
  }

  private async probeCollectionWritable(client: IWebDavBackend, base: string): Promise<WebDavSyncResult | null> {
    const probeName = `.probe_${Date.now()}.txt`;
    const probePath = this.composeRemotePath(base, '', probeName);
    const putRes = await client.put(probePath, 'probe', 'text/plain');
    if (putRes.statusCode >= 200 && putRes.statusCode < 300) {
      await client.delete(probePath);
      return null;
    }
    if (putRes.statusCode === 401 || putRes.statusCode === 403) {
      const msg = putRes.statusCode === 401 ? '鉴权失败（可能需要应用专用密码）' : '权限不足（目录可能不可写）';
      return WebDavSyncResult.fail('WebDAV 连接失败', `STEP remoteRoot PUT ${putRes.statusCode}: ${msg}`);
    }
    if (putRes.statusCode === 404) {
      return WebDavSyncResult.fail('WebDAV 连接失败', `STEP remoteRoot PUT 404: 远端目录不存在或不可用，请先创建 ${this.settings.remoteRoot}`);
    }
    if (putRes.statusCode === 409) {
      return WebDavSyncResult.fail('WebDAV 连接失败', `STEP remoteRoot PUT 409: 路径不存在（AncestorNotFound）；请先创建 ${this.settings.remoteRoot}`);
    }
    return WebDavSyncResult.fail('WebDAV 连接失败', `STEP remoteRoot PUT ${putRes.statusCode}: ${putRes.body}`);
  }

  private async preflightRemoteRoot(client: IWebDavBackend): Promise<WebDavSyncResult | null> {
    const key = `${safeTrim(this.settings.endpoint)}|${safeTrim(this.settings.remoteRoot)}`;
    if (this.remoteLayoutKey === key) {
      return null;
    }

    const remoteRoot = normalizeRoot(this.settings.remoteRoot);
    if (remoteRoot === '/') {
      this.remoteLayoutKey = key;
      this.remoteLayoutBase = '/';
      this.remoteLayoutPrefix = '';
      return null;
    }

    const rootHead = await client.head(remoteRoot);
    if (this.isCollectionReachable(rootHead.statusCode)) {
      this.remoteLayoutKey = key;
      this.remoteLayoutBase = remoteRoot;
      this.remoteLayoutPrefix = '';
      return null;
    }

    // 目录不存在，尝试创建
    if (rootHead.statusCode === 404) {
      console.info(`[WebDavSyncManager] Remote directory ${remoteRoot} not found, trying to create it`);
      const createResult = await this.ensureRemoteDirectory(client, remoteRoot);
      if (createResult !== null) {
        return createResult;
      }
      // 创建成功，重新检查
      const recheckHead = await client.head(remoteRoot);
      if (this.isCollectionReachable(recheckHead.statusCode)) {
        this.remoteLayoutKey = key;
        this.remoteLayoutBase = remoteRoot;
        this.remoteLayoutPrefix = '';
        return null;
      }
    }

    const probeRemoteRoot = await this.probeCollectionWritable(client, remoteRoot);
    if (probeRemoteRoot === null) {
      this.remoteLayoutKey = key;
      this.remoteLayoutBase = remoteRoot;
      this.remoteLayoutPrefix = '';
      return null;
    }

    if (this.settings.requireRemoteRootExists) {
      return probeRemoteRoot;
    }

